package com.ruoyi.paiflow.service;

import com.alibaba.fastjson2.*;
import com.ruoyi.common.exception.ServiceException;
import com.ruoyi.paiflow.domain.*;
import com.ruoyi.paiflow.mapper.*;
import java.time.LocalDateTime;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class DataWorkerOperationTest {
    static class Fixture {
        final RunMapper runs=mock(RunMapper.class);final SpaceMapper spaces=mock(SpaceMapper.class);final RunLeaseService leases=mock(RunLeaseService.class);final DataRuntimeCatalog catalog=mock(DataRuntimeCatalog.class);final DataOperationService operation=mock(DataOperationService.class);final ToolMapper tools=mock(ToolMapper.class);final ModelOperationMapper models=mock(ModelOperationMapper.class);final CheckpointMapper checkpoints=mock(CheckpointMapper.class);final CompletedOutputSources completedOutputs=new CompletedOutputSources(tools,models,checkpoints);final DataWorkerOperationService worker=new DataWorkerOperationService(runs,spaces,leases,catalog,operation,completedOutputs);
        final WorkerIdentityService.Principal identity=new WorkerIdentityService.Principal("python-local","python");final RunRecord run=new RunRecord();final JSONObject descriptor=JSONObject.of("kind","database","provider","center-data","enabled",true,"version","2","tables",new JSONObject());final JSONObject node=JSONObject.of("mode",3,"tableName","people","dataResourceId","data:5:revision:2","assignmentList",new JSONArray(List.of("name")),"orderData",new JSONArray(),"limit",10,"cases",new JSONArray());
        Fixture(){run.setId("33333333-3333-3333-3333-333333333333");run.setSpaceId(2L);run.setOwnerUserId(1L);run.setEngineProfile("python");run.setState("RUNNING");run.setAttempt(1);run.setLeaseId("lease");run.setLastEventSeq(0L);run.setExecutionStartedAt(LocalDateTime.now());run.setAssignmentJson(JSONObject.of("input",new JSONObject(),"dataEnvironment",2,"resourceSnapshots",JSONObject.of("data:5:revision:2",descriptor),"dsl",JSONObject.of("nodes",new JSONArray(List.of(JSONObject.of("id","database::1","data",JSONObject.of("inputs",new JSONArray(),"nodeParam",node)))),"edges",new JSONArray())).toJSONString());when(runs.find(run.getId())).thenReturn(run);when(spaces.lock(2)).thenReturn(new SpaceRecord());when(leases.requireActiveLease(run.getId(),identity,"lease",1)).thenReturn(run);}
        JSONObject payload(){return JSONObject.of("mode",3,"table","people","values",new JSONObject(),"where",JSONObject.of("logicalOperator","and","conditions",new JSONArray()),"columns",new JSONArray(List.of("name")),"order",new JSONArray(),"limit",10,"returning","exec_success","execDev",2);}
        JSONObject request(){return JSONObject.of("leaseId","lease","attempt",1,"nodeId","database::1","operation","data.query","idempotencyKey","key1","parameters",JSONObject.of("kind","database","provider","center-data","resourceId","data:5:revision:2","resourceVersion","2","resourceBindings",new JSONObject(),"legacyPayload",payload()));}
    }
    @Test void httpFacadeReusesLeaseAndReturnsExactLegacyCompletedBinding(){var f=new Fixture();var request=f.request();var legacy=JSONObject.of("code",0,"message","success","data",JSONObject.of("exec_success",new JSONArray()));when(f.operation.execute(eq(f.run),eq("data:5:revision:2"),eq(f.descriptor),eq("data.query"),any(),eq("key1"))).thenReturn(legacy);var ack=f.worker.start(f.run.getId(),f.identity,request);assertEquals("COMPLETED",ack.getString("state"));assertEquals(legacy,ack.get("legacyResponse"));assertEquals("2",ack.getString("resourceVersion"));assertEquals(new JSONObject(),ack.get("resourceBindings"));verify(f.leases,times(2)).requireActiveLease(f.run.getId(),f.identity,"lease",1);}
    @Test void wrongNodeResourceAndSqlTemplateAreRejectedBeforeProducer(){var f=new Fixture();var bad=f.request();bad.put("nodeId","database::another");assertThrows(ServiceException.class,()->f.worker.start(f.run.getId(),f.identity,bad));verifyNoInteractions(f.operation);var other=f.request();other.getJSONObject("parameters").put("resourceId","data:9:revision:2");var resource=other;assertThrows(ServiceException.class,()->f.worker.start(f.run.getId(),f.identity,resource));verifyNoInteractions(f.operation);
        var custom=JSONObject.of("mode",0,"sql","SELECT name FROM people WHERE score>{{score}}");DataWorkerOperationService.validateNode(custom,JSONObject.of("mode",0,"sql","SELECT name FROM people WHERE score>5","execDev",2));assertThrows(ServiceException.class,()->DataWorkerOperationService.validateNode(custom,JSONObject.of("mode",0,"sql","DELETE FROM people","execDev",2)));assertThrows(ServiceException.class,()->DataWorkerOperationService.validateNode(custom,JSONObject.of("mode",0,"sql","SELECT name FROM secrets WHERE score>5","execDev",2)));}
    @Test void structuredTemplatePreventsTableModeProjectionAndConditionChanges(){var f=new Fixture();var p=f.payload();DataWorkerOperationService.validateNode(f.node,p);p.put("table","sys_user");assertThrows(ServiceException.class,()->DataWorkerOperationService.validateNode(f.node,p));p.put("table","people");p.put("columns",new JSONArray(List.of("password")));assertThrows(ServiceException.class,()->DataWorkerOperationService.validateNode(f.node,p));p.put("columns",new JSONArray(List.of("name")));p.put("mode",4);assertThrows(ServiceException.class,()->DataWorkerOperationService.validateNode(f.node,p));}
    @Test void actualPythonOriginalConsumerFixturesAreAcceptedWithExactBinding() throws Exception {
        // 16份请求由真实PGSqlNode→node_capabilities→legacy_operations执行捕获；中心仅隔离fixture。
        try(InputStream input=getClass().getClassLoader().getResourceAsStream("paiflow/data-consumer-fixtures.json")){
            assertNotNull(input,"实际Python请求fixture必须随测试资源提供");var document=JSON.parseObject(new String(input.readAllBytes(),StandardCharsets.UTF_8));assertEquals("paiflow.data.actual-consumer-fixtures.v1",document.getString("schemaVersion"));var cases=document.getJSONArray("cases");assertEquals(16,cases.size());
            for(Object raw:cases){var sample=(JSONObject)raw;var f=new Fixture();var params=sample.getJSONObject("parameters");String resource=params.getString("resourceId");var request=assignSample(f,sample);
                var legacy=JSONObject.of("code",0,"message","success","data",JSONObject.of("exec_success",new JSONArray()));when(f.operation.execute(eq(f.run),eq(resource),eq(f.descriptor),eq(sample.getString("operation")),eq(params.getJSONObject("legacyPayload")),eq("key1"))).thenReturn(legacy);var response=f.worker.start(f.run.getId(),f.identity,request);assertEquals("COMPLETED",response.getString("state"),sample.getString("name"));for(String key:List.of("kind","provider","resourceId","resourceVersion","resourceBindings"))assertEquals(params.get(key),response.get(key),sample.getString("name")+"/"+key);assertEquals(legacy,response.get("legacyResponse"));verify(f.operation).execute(f.run,resource,f.descriptor,sample.getString("operation"),params.getJSONObject("legacyPayload"),"key1");
            }
        }
    }
    private static JSONObject assignSample(Fixture fixture,JSONObject sample){var params=sample.getJSONObject("parameters");String resource=params.getString("resourceId");var assigned=JSON.parseObject(fixture.run.getAssignmentJson());assigned.put("dataEnvironment",params.getJSONObject("legacyPayload").get("execDev"));assigned.put("input",JSONObject.of("question","原查询","bundle",JSONObject.of("nested",new JSONArray(List.of(JSONObject.of("business","原透传"))))));assigned.put("resourceSnapshots",JSONObject.of(resource,fixture.descriptor));var data=assigned.getJSONObject("dsl").getJSONArray("nodes").getJSONObject(0).getJSONObject("data");data.put("nodeParam",sample.getJSONObject("node"));var inputs=sample.getJSONArray("nodeInputs");assertNotNull(inputs,"固定输入必须来自真实Python捕获");data.put("inputs",inputs);fixture.run.setAssignmentJson(assigned.toJSONString());var request=fixture.request();request.put("operation",sample.get("operation"));request.put("parameters",params);return request;}
    @Test void originalAddInputsFixWritableColumnsAndBindValuesToActualRunInput() throws Exception {
        JSONObject sample;try(InputStream input=getClass().getClassLoader().getResourceAsStream("paiflow/data-consumer-fixtures.json")){assertNotNull(input);sample=JSON.parseObject(new String(input.readAllBytes(),StandardCharsets.UTF_8)).getJSONArray("cases").stream().map(JSONObject.class::cast).filter(value->"mode-1-env-2".equals(value.getString("name"))).findFirst().orElseThrow();}
        var fixture=new Fixture();fixture.descriptor.put("tables",JSONObject.of("items",JSONObject.of("columns",new JSONArray(List.of("name","count","question","bundle")))));var request=assignSample(fixture,sample);
        var extra=JSON.parseObject(request.toJSONString(JSONWriter.Feature.WriteMapNullValue));extra.getJSONObject("parameters").getJSONObject("legacyPayload").getJSONObject("values").put("count",99);
        assertEquals(409,assertThrows(ServiceException.class,()->fixture.worker.start(fixture.run.getId(),fixture.identity,extra)).getCode());verifyNoInteractions(fixture.operation);
        var missing=JSON.parseObject(request.toJSONString(JSONWriter.Feature.WriteMapNullValue));missing.getJSONObject("parameters").getJSONObject("legacyPayload").getJSONObject("values").remove("question");
        assertEquals(409,assertThrows(ServiceException.class,()->fixture.worker.start(fixture.run.getId(),fixture.identity,missing)).getCode());verifyNoInteractions(fixture.operation);
        var values=request.getJSONObject("parameters").getJSONObject("legacyPayload").getJSONObject("values");values.put("question","运行中的动态值");values.put("bundle",JSONObject.of("nested",new JSONArray(List.of("动态对象"))));
        var legacy=JSONObject.of("code",0,"message","success","data",JSONObject.of("exec_success",new JSONArray()));when(fixture.operation.execute(eq(fixture.run),eq("data:7:revision:2"),eq(fixture.descriptor),eq("data.mutate"),any(),eq("key1"))).thenReturn(legacy);
        assertEquals(409,assertThrows(ServiceException.class,()->fixture.worker.start(fixture.run.getId(),fixture.identity,request)).getCode());verifyNoInteractions(fixture.operation);var fixed=JSON.parseObject(fixture.run.getAssignmentJson());fixed.put("input",JSON.parseObject(values.toJSONString(JSONWriter.Feature.WriteMapNullValue)));fixture.run.setAssignmentJson(fixed.toJSONString(JSONWriter.Feature.WriteMapNullValue));request.getJSONObject("parameters").put("legacyPayload",DataInputPayload.expected(fixed.getJSONObject("dsl"),fixed.getJSONObject("dsl").getJSONArray("nodes").getJSONObject(0),fixed.getJSONObject("input"),new JSONArray(),2));assertEquals("COMPLETED",fixture.worker.start(fixture.run.getId(),fixture.identity,request).getString("state"));verify(fixture.operation).execute(fixture.run,"data:7:revision:2",fixture.descriptor,"data.mutate",request.getJSONObject("parameters").getJSONObject("legacyPayload"),"key1");
    }
    @Test void admissionDerivesReadAndWriteFromFixedSqlAndActualNodes(){var fixture=new DataOperationTest.Fixture();var read=JSONObject.of("id","database::r","data",JSONObject.of("nodeParam",JSONObject.of("mode",0,"sql","SELECT name FROM people WHERE name='{{name}}'","dataResourceId",DataOperationTest.RESOURCE)));var write=JSONObject.of("id","database::w","data",JSONObject.of("nodeParam",JSONObject.of("mode",0,"sql","UPDATE people SET score={{score}} WHERE id=1","dataResourceId",DataOperationTest.RESOURCE)));var resources=JSONObject.of(DataOperationTest.RESOURCE,fixture.descriptor);var execution=JSONObject.of("nodes",new JSONArray(List.of(read,write)));assertEquals(Set.of("data.query","data.mutate"),fixture.operation.admit(2,1,resources,execution,2));verify(fixture.catalog).requireOwner(2,1,true);verify(fixture.catalog).requireOwner(2,1,false);verifyNoInteractions(fixture.rows);}
}


